<template x-if="['onus','degradation'].includes(modal)">
    <div class="onu-workspace">
        <div class="onu-fleet-overview">
            <div class="onu-fleet-intro"><span class="onu-fleet-icon"><i data-lucide="network"></i></span><div><span class="eyebrow">CONNECTION OVERVIEW</span><h3>Setiap koneksi, dalam satu pandangan.</h3><p>Ringkasan OLT dan PON yang dipilih.</p></div></div>
            <div class="onu-health-track"><div><span>ONU online</span><strong x-text="onuScopeSummary.percent+'%'"></strong></div><span class="onu-health-rail"><span :style="'width:'+onuScopeSummary.percent+'%'"></span></span></div>
            <div class="onu-fleet-metrics">
                <div><span>Total ONU</span><strong x-text="onuScopeSummary.total"></strong><small>Perangkat terdaftar</small></div>
                <div class="is-online"><span><i class="dot green"></i> Online</span><strong x-text="onuScopeSummary.online"></strong><small>Koneksi working</small></div>
                <div><span>Belum online</span><strong x-text="onuScopeSummary.other"></strong><small>Offline / proses koneksi</small></div>
                <div class="is-attention"><span>Optik perlu perhatian</span><strong x-text="onuScopeSummary.weak"></strong><small x-text="'Rx ≤ '+db.threshold+' dBm'"></small></div>
            </div>
        </div>
        <div class="onu-directory-heading"><div><h3>Direktori ONU</h3><p>Cari pelanggan, periksa sinyal, dan kelola koneksi.</p></div><span class="onu-directory-count" x-text="(db.compact?directory.total:modalOnus.length)+' hasil'"></span></div>
        <p class="muted" x-show="modal==='degradation'">ONU turun minimal 3 dB dibanding rata-rata 24 jam, dengan minimal 3 sampel baseline. Pembacaan lebih lama dari 15 menit dikecualikan. Dihitung <span x-text="db.optical_calculated_at"></span>; dibandingkan observasi sebelumnya.</p>
        <div class="notice" x-show="modal==='onus' && selected?.connection_mode!=='real' && db.demo"><i data-lucide="info"></i>Data simulasi lokal. Reboot berjalan sekitar 8 detik dan status diperbarui otomatis.</div>
        @include('partials.skeleton',['show'=>'directoryBusy&&!directory.data.length'])
        <div class="onu-table-controls">
            <label class="modal-search"><i data-lucide="search"></i><input x-model.debounce.250ms="modalQuery" placeholder="Cari pelanggan, SN, deskripsi, atau tag..." aria-label="Cari dalam tabel ONU"></label>
            <label class="compact-field" x-show="!selected">OLT<select x-model="onuOlt" aria-label="Filter OLT ONU"><option value="all">Semua OLT</option><template x-for="olt in db.olts" :key="olt.id"><option :value="String(olt.id)" x-text="olt.name"></option></template></select></label>
            <label class="compact-field" x-show="selected">PON<select x-model="onuPort" aria-label="Filter PON"><option value="all">Semua PON</option><template x-for="port in selected?.ports || []" :key="port.id"><option :value="String(port.id)" x-text="port.interface_name"></option></template></select></label>
            <label class="compact-field">Status ONU<select x-model="onuStatus" aria-label="Filter status ONU"><option value="all">Semua status</option><option value="nonworking">Semua yang tidak online</option><option value="working">working</option><option value="sync-mib">Sync MIB</option><option value="logging">Logging</option><option value="auth">Auth</option><option value="los">los</option><option value="dying-gasp">dying-gasp</option><option value="offline">offline</option><option value="poweroff">Power off</option><option value="restorefail">Restore fail</option><option value="rebooting">rebooting</option></select></label>
        </div>
        <div class="module-toolbar onu-directory-tools"><div class="onu-quick-filters" role="group" aria-label="Status cepat"><button @click="onuStatus='all'" :aria-pressed="onuStatus==='all'">Semua</button><button @click="onuStatus='working'" :aria-pressed="onuStatus==='working'"><span class="dot green"></span>Online</button><button x-show="!isYotc(selected)" @click="onuStatus='los'" :aria-pressed="onuStatus==='los'"><span class="dot red"></span>LOS</button></div><button class="btn secondary" @click="columnsOpen=!columnsOpen" :aria-expanded="columnsOpen"><i data-lucide="columns-3"></i>Kolom</button><button class="btn secondary" @click="exportOnus()"><i data-lucide="download"></i>Ekspor CSV</button><label>Baris<select x-model.number="onuPageSize"><option :value="25">25</option><option :value="50">50</option></select></label></div>
        <div class="inline-editor tag-checkboxes" x-show="columnsOpen"><template x-for="column in [{key:'status',name:'Status'},{key:'rx',name:'Redaman ONT'},{key:'last_online',name:'Terakhir online'},{key:'serial',name:'Serial'},{key:'traffic',name:'Traffic'},{key:'description',name:'Deskripsi'},{key:'pppoe',name:'PPPoE'},{key:'vlan',name:'VLAN'},{key:'tags',name:'Tags'}]" :key="column.key"><label x-show="column.key!=='traffic'||onuTrafficAvailable()"><input type="checkbox" :checked="columnVisible(column.key)" @change="toggleColumn(column.key)"><span x-text="column.name"></span></label></template></div>
        <div class="signal-legend"><span class="green-text">● Normal ≥ -25 dBm</span><span class="amber-text">● Waspada > -27 dBm</span><span class="red-text">● Buruk &le; -27 dBm</span></div>
        <template x-if="tagOnu">
            <form id="onu-tag-editor" tabindex="-1" class="inline-editor" @submit.prevent="saveOnuTags()">
                <strong>Tags · <span x-text="tagOnu.name"></span></strong>
                <div class="tag-checkboxes"><template x-for="tag in db.tags" :key="tag.id"><label><input type="checkbox" :value="String(tag.id)" x-model="onuTagIds"><span class="dot" :style="'background:'+tag.color_hex"></span><span x-text="tag.tag_name"></span></label></template></div>
                <p class="muted small" x-show="!db.tags.length">Belum ada tag. Tambahkan melalui menu Tags.</p>
                <div class="modal-actions"><button type="button" class="btn secondary" @click="tagOnu=null" :disabled="busy">Batal</button><button class="btn primary" :disabled="busy">Simpan tag ONU</button></div>
            </form>
        </template>
        <p class="small muted" aria-live="polite"><span x-text="(db.compact?directory.total:modalOnus.length)"></span> ONU ditemukan</p>
        <div class="table-scroll operational-table onu-reference-table" tabindex="0" role="region" aria-label="Tabel ONU, gulir untuk melihat seluruh kolom"><table><thead><tr>
            <th scope="col" :aria-sort="onuSortState('name')"><button class="table-sort" @click="sortOnus('name')">Nama <span aria-hidden="true" x-text="onuSortIcon('name')"></span></button></th>
            <th x-show="!selected">OLT</th>
            <th scope="col" x-show="columnVisible('status')" :aria-sort="onuSortState('status')"><button class="table-sort" @click="sortOnus('status')">Status <span aria-hidden="true" x-text="onuSortIcon('status')"></span></button></th>
            <th scope="col" :aria-sort="onuSortState('position')"><button class="table-sort" @click="sortOnus('position')">Posisi <span aria-hidden="true" x-text="onuSortIcon('position')"></span></button></th>
            <th scope="col" x-show="columnVisible('rx')" :aria-sort="onuSortState('rx_power')"><button class="table-sort" @click="sortOnus('rx_power')">Redaman ONT <span aria-hidden="true" x-text="onuSortIcon('rx_power')"></span></button></th>
            <th scope="col" x-show="columnVisible('last_online')" :aria-sort="onuSortState('last_online_at')"><button class="table-sort" @click="sortOnus('last_online_at')">Terakhir online <span aria-hidden="true" x-text="onuSortIcon('last_online_at')"></span></button></th>
            <th scope="col" x-show="columnVisible('serial')" :aria-sort="onuSortState('sn')"><button class="table-sort" @click="sortOnus('sn')">Serial <span aria-hidden="true" x-text="onuSortIcon('sn')"></span></button></th>
            <th x-show="columnVisible('traffic')" scope="col" title="Traffic dari dua sampel SNMP IF-MIB">Traffic &darr; / &uarr;</th><th x-show="modal==='degradation'">Baseline / Penurunan</th><th x-show="columnVisible('description')">Deskripsi</th><th x-show="columnVisible('pppoe')">PPPoE</th><th x-show="columnVisible('vlan')">VLAN</th><th x-show="columnVisible('tags')">Tags</th><th scope="col">Aksi</th></tr></thead>
            <tbody><template x-for="onu in pagedOnus" :key="onu.id"><tr>
                <td class="onu-name-cell"><div class="onu-identity"><span class="onu-device-avatar" :class="{'is-online':onu.phase_state==='working'}"><i data-lucide="router"></i></span><div><button type="button" class="text-button onu-name-link" @click="inspectOnu(onu)" x-text="onuDisplayName(onu)"></button><small x-text="onu.interface"></small></div></div></td>
                <td x-show="!selected" x-text="oltName(onu.olt_id)"></td>
                <td x-show="columnVisible('status')"><span class="onu-state" :class="phaseClass(onu.phase_state)"><span class="dot" :class="onu.phase_state==='working'?'green':onu.phase_state==='los'?'red':'gray'"></span><span x-text="onuState(onu.phase_state)"></span><small x-show="onu.admin_state==='disable'">Nonaktif</small></span></td>
                <td class="mono onu-position" :title="oltName(onu.olt_id)+' / '+onu.interface" x-text="onuPosition(onu)"></td>
                <td x-show="columnVisible('rx')" class="mono onu-rx" :class="signalClass(onu)" :title="signalLabel(onu)"><span x-text="rx(onu.rx_power)"></span><span class="sr-only" x-text="signalLabel(onu)"></span></td>
                <td x-show="columnVisible('last_online')" class="muted onu-last-online" :title="onu.last_online_at?'Terakhir teramati online: '+dateTime(onu.last_online_at):'Belum ada observasi online'" x-text="onu.last_online_at?dateTime(onu.last_online_at):'—'"></td>
                <td x-show="columnVisible('serial')" class="mono onu-serial" x-text="onu.sn"></td><td x-show="columnVisible('traffic')" class="muted onu-traffic" :title="!onuSupports(onu,'onu_traffic')?'Traffic per ONU belum tersedia':onu.traffic_observed_at?'Diperiksa '+dateTime(onu.traffic_observed_at):'Menunggu dua sampel SNMP interface yang cocok'" x-text="onuSupports(onu,'onu_traffic')?traffic(onu):'Belum tersedia'"></td>
                <td x-show="modal==='degradation'" class="mono"><span x-text="rx(onu.previous_rx)"></span><small class="red-text" x-text="onu.previous_rx == null || onu.rx_power == null ? 'Belum tersedia' : Number(onu.delta_db??(onu.rx_power-onu.previous_rx)).toFixed(2)+' dB'"></small><small class="amber-text" x-show="onu.correlated_count>=2" x-text="onu.correlated_count+' ONU menurun pada PON ini'"></small></td>
                <td x-show="columnVisible('description')" x-text="onu.description||'—'"></td><td x-show="columnVisible('pppoe')" x-text="onu.pppoe_user||'—'"></td><td x-show="columnVisible('vlan')" x-text="onu.vlan_id??'—'"></td><td x-show="columnVisible('tags')" x-text="onu.tags.map(t=>t.tag_name).join(', ')"></td>
                <td class="onu-row-actions"><button type="button" class="icon-button" @click="inspectOnu(onu)" :aria-label="'Detail ONU '+onu.sn+' posisi '+onuPosition(onu)" title="Detail ONU"><i data-lucide="eye"></i></button><button type="button" class="icon-button reboot-button" x-show="modal==='onus' && db.permissions.operate && onuSupports(onu,'reboot')" @click="confirmAction('reboot',onu)" :disabled="busy || onu.phase_state==='rebooting'" :aria-label="onu.phase_state==='rebooting'?'Rebooting...':'Reboot ONU'" title="Reboot ONU"><i data-lucide="rotate-cw" :class="{'spinning':onu.phase_state==='rebooting'}"></i></button><button type="button" class="icon-button" @click="inspectOnu(onu)" :aria-label="'Opsi ONU '+onu.sn" title="Opsi ONU"><i data-lucide="more-horizontal"></i></button></td>
            </tr></template></tbody>
        </table></div>
        <div class="pagination"><button class="btn secondary" @click="onuPage--" :disabled="onuPage<=1">Halaman sebelumnya</button><span class="small muted" x-text="'Halaman '+onuPage+' / '+onuPageCount"></span><button class="btn secondary" @click="onuPage++" :disabled="onuPage>=onuPageCount">Halaman berikutnya</button></div>
        <div class="empty-state" x-show="!(db.compact?directory.total:modalOnus.length)"><i data-lucide="search-x"></i>Tidak ada ONU sesuai filter.<button class="text-button" @click="modalQuery='';onuStatus='all';onuPort='all'">Reset filter</button></div>
    </div>
</template>
